        openDate: null,
        closingDate: null,
        advertisedDate: null,
        employmentCategory: null,
        employmentEnd: null,
        status: "open",
        positionRef: null,
        positionResource: null,
      },
      afterSaveMessage: "",
    };
  },

  computed: {
    isInternalApplicant() {
      const exts = this.$store?.state?.user?.obj?.resource?.extension || [];
      return !!exts.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
      );
    },

    practitionerId() {
      const exts = this.$store?.state?.user?.obj?.resource?.extension || [];
      const ref = exts.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
      )?.valueReference?.reference;
      return ref ? ref.split("/")[1] : null;
    },

    advertId() {
      return (
        this.queries?.advertId ||
        this.queries?.advert ||
        this.queries?.id ||
        null
      );
    },

    // Each of the four lists below follows the same shape:
    // { category, label, sourceReference }. sourceReference identifies the
    // record an attachment supports: a real "Basic/{id}" reference for
    // internal-staff resources (EducationHistoryProfile / LSRegistrationProfile,
    // each its own resource), or a positional pseudo-reference like
    // "post-secondary-education[N]" for external-applicant sub-extensions,
    // which have no resource id of their own.

    educationAttachments() {
      if (this.isInternalApplicant) {
        return this.internalEducationRecords.map((r) => {
          const ext = (r.extension || []).find((e) =>
            e.url.endsWith("/education-history"),
          );
          const institution = ext?.extension?.find(
            (x) => x.url === "institution",
          )?.valueString;
          const qualOther = ext?.extension?.find(
            (x) => x.url === "qualification-name-other",
          )?.valueString;
          return {
            category: "education",
            label:
              [institution, qualOther].filter(Boolean).join(" — ") ||
              "Education record",
            sourceReference: "Basic/" + r.id,
          };
        });
      }
      const exts = this.profile?.extension || [];
      return exts
        .filter((e) => e.url.endsWith("/post-secondary-education"))
        .map((ext, idx) => {
          const institution = ext.extension?.find(
            (x) => x.url === "institution-name",
          )?.valueString;
          const qualOther = ext.extension?.find(
            (x) => x.url === "qualification-name-other",
          )?.valueString;
          return {
            category: "education",
            label:
              [institution, qualOther].filter(Boolean).join(" — ") ||
              `Education record ${idx + 1}`,
            sourceReference: `post-secondary-education[${idx}]`,
          };
        });
    },

    councilAttachments() {
      if (this.isInternalApplicant) {
        return this.internalCouncilRecords.map((r) => {
          const coding = (r.extension || []).find(
            (e) => e.url.endsWith("/registration-council"),
          )?.valueCoding;
          const regNumber = (r.extension || []).find((e) =>
            e.url.endsWith("/registration-number"),
          )?.valueString;
          return {
            category: "council",
            label:
              [coding?.display || coding?.code, regNumber]
                .filter(Boolean)
                .join(" — ") || "Council registration",
            sourceReference: "Basic/" + r.id,
          };
        });
      }
      const exts = this.profile?.extension || [];
      return exts
        .filter((e) => e.url.endsWith("/council-registration"))
        .map((ext, idx) => {
          const coding = ext.extension?.find(
            (x) => x.url === "council",
          )?.valueCoding;
          const regNumber = ext.extension?.find(
            (x) => x.url === "registration-number",
          )?.valueString;
          return {
            category: "council",
            label:
              [coding?.display || coding?.code, regNumber]
                .filter(Boolean)
                .join(" — ") || `Council registration ${idx + 1}`,
            sourceReference: `council-registration[${idx}]`,
          };
        });
    },

    // External applicants only — staff don't submit a national ID at
    // application time.
    nationalIdAttachment() {
      if (this.isInternalApplicant) return null;
      const nationalId = (this.profile?.extension || []).find((e) =>
        e.url.endsWith("/national-id"),
      )?.valueString;
      if (!nationalId) return null;
      return {
        category: "national-id",
        label: "National ID",
        sourceReference: "national-id",
      };
    },

    // External applicants only — referee letters, one per listed
    // personal-reference entry.
    refereeAttachments() {
      if (this.isInternalApplicant) return [];
      const exts = this.profile?.extension || [];
      return exts
        .filter((e) => e.url.endsWith("/personal-reference"))
        .map((ext, idx) => {
          const name = ext.extension?.find(
            (x) => x.url === "name",
          )?.valueString;
          return {
            category: "referee",
            label: name || `Referee ${idx + 1}`,
            sourceReference: `personal-reference[${idx}]`,
          };
        });
    },

    // External applicants only — no staff equivalent exists for this
    // profile field.
    additionalQualificationAttachments() {
      if (this.isInternalApplicant) return [];
      const exts = this.profile?.extension || [];
      return exts
        .filter((e) => e.url.endsWith("/additional-qualifications"))
        .map((ext, idx) => {
          const qualName = ext.extension?.find(
            (x) => x.url === "qualification-name",
          )?.valueString;
          return {
            category: "additional-qualification",
            label: qualName || `Additional Qualification ${idx + 1}`,
            sourceReference: `additional-qualifications[${idx}]`,
          };
        });
    },

    allAttachments() {
      const list = [
        ...this.educationAttachments,
        ...this.councilAttachments,
        ...this.additionalQualificationAttachments,
        ...this.refereeAttachments,
      ];
      if (this.nationalIdAttachment) list.push(this.nationalIdAttachment);
      return list;
    },

    missingRequiredAttachments() {
      return this.allAttachments.some(
        (item) => !this.attachmentFiles[item.sourceReference],
      );
    },

    today() {
      return new Date().toISOString().split("T")[0];
    },

    isOpen() {
      if (!this.advert.openDate || !this.advert.closingDate) return false;
      return (
        this.advert.openDate <= this.today &&
        this.advert.closingDate >= this.today
      );
    },

    isClosingSoon() {
      if (!this.advert.closingDate) return false;
      const diff = new Date(this.advert.closingDate) - new Date();
      return diff > 0 && diff < 7 * 86400000;
    },

    daysRemaining() {
      if (!this.advert.closingDate) return 0;
      return Math.ceil(
        (new Date(this.advert.closingDate) - new Date()) / 86400000,
      );
    },

    advertisementDays() {
      if (!this.advert.openDate || !this.advert.closingDate) return 0;
      return Math.floor(
        (new Date(this.advert.closingDate) - new Date(this.advert.openDate)) /
          86400000,
      );
    },

    closingProgress() {
      if (!this.advert.openDate || !this.advert.closingDate) return 0;
      const total =
        new Date(this.advert.closingDate) - new Date(this.advert.openDate);
      const elapsed = new Date() - new Date(this.advert.openDate);
      return Math.min(Math.max((elapsed / total) * 100, 0), 100);
    },

    countdownClass() {
      if (this.daysRemaining < 0) return "ap-countdown--expired";
      if (this.isClosingSoon) return "ap-countdown--urgent";
      if (this.isOpen) return "ap-countdown--open";
      return "ap-countdown--pending";
    },

    daysLabel() {
      if (this.daysRemaining === 0) return "closing today";
      return this.daysRemaining < 0 ? "days ago" : "days remaining";
    },

    countdownBarColor() {
      if (this.daysRemaining < 0) return "#6b7280";
      if (this.isClosingSoon) return "#ef4444";
      if (this.closingProgress > 70) return "#f97316";
      return "#0d9488";
    },
  },

  watch: {
    // App.vue's updateConfig() (which actually commits the logged-in user
    // to the store) runs asynchronously and isn't awaited by the router
    // guard, so on a direct page load/refresh this component's mounted()
    // hook can call loadProfile() before $store.state.user.obj.resource is
    // populated — loadProfile then finds no reference and gives up for
    // good, showing "No profile found" even though the user is logged in.
    // Re-run profile/application loading once the user resource actually
    // shows up.
    "$store.state.user.obj.resource"(resource) {
      if (!resource || this.profile) return;
      this.loadProfile();
      this.checkExistingApplication();
      this.loadAttachmentRecords();
    },
  },

  async mounted() {
    if (!this.advertId) {
      this.notFound = true;
      this.loading = false;
      return;
    }
    await this.loadVacancy();
    await this.loadProfile();
    await this.checkExistingApplication();
    await this.loadAttachmentRecords();
  },

  methods: {
    async checkExistingApplication() {
      if (!this.advertId) return;
      // resolve applicant or practitioner id
      const exts = this.$store?.state?.user?.obj?.resource?.extension || [];
      const applicantRef = exts.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-external-applicant-reference",
      )?.valueReference?.reference;
      const practitionerRef = exts.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
      )?.valueReference?.reference;
      const applicantId = applicantRef ? applicantRef.split("/")[1] : null;
      const practitionerId = practitionerRef
        ? practitionerRef.split("/")[1]
        : null;
      if (!applicantId && !practitionerId) return;
      this.checkingApplication = true;
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/application-profile",
          advertisedvacancy: "Basic/" + this.advertId,
        });
        if (practitionerId) {
          params.set("practitioner", "Practitioner/" + practitionerId);
        } else {
          params.set("basicapplicant", "Basic/" + applicantId);
        }
        const res = await fetch("/fhir/Basic?" + params.toString());
        if (res.ok) {
          const bundle = await res.json();
          if (bundle.entry && bundle.entry.length > 0) {
            this.hasApplied = true;
          }
        }
      } catch (e) {
        console.error("checkExistingApplication error", e);
      } finally {
        this.checkingApplication = false;
      }
    },

    async fetchBasicByProfile(profileUrl) {
      if (!this.practitionerId) return [];
      const params = new URLSearchParams({
        _profile: profileUrl,
        practitioner: "Practitioner/" + this.practitionerId,
      });
      const res = await fetch("/fhir/Basic?" + params.toString());
      if (!res.ok) return [];
      const bundle = await res.json();
      return (bundle.entry || []).map((e) => e.resource);
    },

    async loadAttachmentRecords() {
      // National ID and referee letters are derived directly from
      // this.profile (external applicants only), so only education and
      // council registration need a fetch — and only for internal staff,
      // whose records live in their own separate Basic resources.
      if (!this.isInternalApplicant || !this.practitionerId) return;
      this.attachmentsLoading = true;
      try {
        const [education, council] = await Promise.all([
          this.fetchBasicByProfile(
            "http://ihris.org/fhir/StructureDefinition/education-history-profile",
          ),
          this.fetchBasicByProfile(
            "http://ihris.org/fhir/StructureDefinition/ls-registration-profile",
          ),
        ]);
        this.internalEducationRecords = education;
        this.internalCouncilRecords = council;
      } catch (e) {
        console.error("loadAttachmentRecords error", e);
      } finally {
        this.attachmentsLoading = false;
      }
    },

    fileToAttachment(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
          const base64 = String(reader.result).split(",")[1] || "";
          resolve({ contentType: file.type, data: base64, title: file.name });
        };
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
      });
    },

    async onAttachmentFileChange(sourceReference, file) {
      if (!file) {
        this.$delete(this.attachmentFiles, sourceReference);
        return;
      }
      try {
        const attachment = await this.fileToAttachment(file);
        this.$set(this.attachmentFiles, sourceReference, attachment);
      } catch (e) {
        console.error("onAttachmentFileChange error", e);
      }
    },

    async loadProfile() {
      if (this.isInternalApplicant) {
        // InternalApplicantProfile component fetches its own data;
        // set profile to truthy so the template renders the profile section.
        this.profile = { _internal: true };
        return;
      }
      const ref = this.$store?.state?.user?.obj?.resource?.extension?.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-external-applicant-reference",
      )?.valueReference?.reference;
      const profileId = ref ? ref.split("/")[1] : null;
      if (!profileId) return;
      this.profileLoading = true;
      try {
        const res = await fetch(`/fhir/Basic/${profileId}`);
        if (res.ok) this.profile = await res.json();
      } catch (e) {
        console.error("loadProfile error", e);
      } finally {
        this.profileLoading = false;
      }
    },

    editProfile() {
      const ref = this.$store?.state?.user?.obj?.resource?.extension?.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-external-applicant-reference",
      )?.valueReference?.reference;
      const profileId = ref ? ref.split("/")[1] : null;
      if (!profileId) return;
      this.$router.push({
        path: "/custom/signup",
        query: { path: "/lesotho/components/recruitment", editId: profileId },
      });
    },

    createProfile() {
      this.$router.push({
        path: "/custom/signup",
        query: { path: "/lesotho/components/recruitment" },
      });
    },

    async submitApplication() {
      if (!this.advert.id) return;
      if (!this.isInternalApplicant && !this.profile) return;
      if (this.missingRequiredAttachments) {
        this.submitError =
          "Please attach a supporting document for every item listed below before submitting.";
        return;
      }
      this.submitting = true;
      this.submitError = null;
      try {
        this.fhir = this.isInternalApplicant
          ? { advertId: this.advert.id, practitionerId: this.practitionerId }
          : { advertId: this.advert.id, applicantId: this.profile.id };
        this.fhir.attachments = this.allAttachments.map((item) => ({
          file: this.attachmentFiles[item.sourceReference],
          title: item.label,
          description: item.label,
          sourceReference: item.sourceReference,
        }));
        this.afterSaveMessage =
          "Thank you for applying! Your application has been received.";
        await this.processFHIR();
        this.submitSuccess = true;
        this.$router.push({
          path: "/custom/my-applications",
          query: {
            path: "/lesotho/components/recruitment",
          },
        });
      } catch (error) {
        console.error("submitApplication error", error);
        this.submitError =
          error.message || "Failed to submit application. Please try again.";
      } finally {
        this.submitting = false;
      }
    },

    async loadVacancy() {
      this.loading = true;
      try {
        const res = await fetch(
          `/site/unauthenticated/open-vacancy/${this.advertId}`,
        );
        if (res.status === 404) {
          this.notFound = true;
          return;
        }
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        this.advert = { ...this.advert, ...data };
        // Build a minimal FHIR resource from position extensions included in the response
        if (
          data.positionId &&
          data.positionExtensions &&
          data.positionExtensions.length
        ) {
          this.positionResource = {
            id: data.positionId,
            resourceType: "Basic",
            extension: data.positionExtensions,
          };
        }
      } catch (err) {
        console.error("loadVacancy error", err);
        this.notFound = true;
      } finally {
        this.loading = false;
      }
    },

    goBack() {
      this.$router.push({
        path: "/custom/advertised-positions",
        query: { path: "/lesotho/components/recruitment" },
      });
    },

    scrollToForm() {
      const el = document.getElementById("application-form");
      if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
    },

    statusLabel(status) {
      return (
        { open: "Open", closed: "Apps Closed", pending: "Not Yet Open" }[
          status
        ] || status
      );
    },

    formatDate(dateStr) {
      if (!dateStr) return "—";
      return new Date(dateStr).toLocaleDateString("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      });
    },
  },
};
</script>

