<template>
  <div class="ps-root">
    <!-- Loading -->
    <div v-if="loading" class="ps-loading">
      <v-progress-circular size="20" width="2" indeterminate color="#4338ca" />
      <span class="ps-loading__text">Loading specifications…</span>
    </div>

    <!-- Error -->
    <div v-else-if="error" class="ps-empty">{{ error }}</div>

    <!-- Empty -->
    <div v-else-if="!specifications.length" class="ps-empty">
      No qualifying pathways defined for this position.
    </div>

    <!-- Pathways -->
    <div v-else class="ps-pathways">
      <div v-for="(spec, si) in specifications" :key="si">

        <!-- AND / OR bridge between pathways -->
        <div v-if="si > 0" class="ps-pathway-bridge">
          <div class="ps-pathway-bridge__track">
            <div class="ps-pathway-bridge__dot"></div>
            <div class="ps-pathway-bridge__line"></div>
            <div class="ps-pathway-bridge__pill">
              {{ (spec.groupOperator || "OR").toUpperCase() }}
            </div>
            <div class="ps-pathway-bridge__line"></div>
            <div class="ps-pathway-bridge__dot"></div>
          </div>
        </div>

        <!-- Pathway card -->
        <div class="ps-pathway">
          <div class="ps-pathway__label">Pathway {{ si + 1 }}</div>

          <!-- Qualifications -->
          <div v-if="spec.qualificationCriteria && spec.qualificationCriteria.length" class="ps-pathway__group">
            <div class="ps-pathway__group-head">
              <v-icon size="14" color="#6366f1">mdi-school-outline</v-icon>
              <span>Qualifications</span>
            </div>
            <div class="ps-crit-list">
              <div v-for="(qc, qi) in spec.qualificationCriteria" :key="'q' + qi">
                <div v-if="qi > 0" class="ps-crit-bridge">
                  <div class="ps-crit-bridge__line"></div>
                  <span class="ps-crit-op ps-crit-op--indigo">
                    {{ (qc.criterionOperator || "OR").toUpperCase() }}
                  </span>
                  <div class="ps-crit-bridge__line"></div>
                </div>
                <div class="ps-crit-card ps-crit-card--indigo">
                  <div class="ps-crit-icon ps-crit-icon--indigo">
                    <v-icon size="13" color="#6366f1">mdi-certificate-outline</v-icon>
                  </div>
                  <div class="ps-crit-content">
                    <span v-if="qc.qualificationLevel" class="ps-crit-badge ps-crit-badge--indigo">
                      {{ qc.qualificationLevel }}
                    </span>
                    <span v-if="qc.qualificationName" class="ps-crit-name">{{ qc.qualificationName }}</span>
                    <span v-if="!qc.qualificationLevel && !qc.qualificationName" class="ps-crit-empty">
                      Any qualification
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- Experience -->
          <div v-if="spec.experienceCriteria && spec.experienceCriteria.length" class="ps-pathway__group">
            <div class="ps-pathway__group-head">
              <v-icon size="14" color="#0d9488">mdi-briefcase-clock-outline</v-icon>
              <span>Experience</span>
            </div>
            <div class="ps-crit-list">
              <div v-for="(ec, ei) in spec.experienceCriteria" :key="'e' + ei">
                <div v-if="ei > 0" class="ps-crit-bridge">
                  <div class="ps-crit-bridge__line"></div>
                  <span class="ps-crit-op ps-crit-op--teal">
                    {{ (ec.criterionOperator || "OR").toUpperCase() }}
                  </span>
                  <div class="ps-crit-bridge__line"></div>
                </div>
                <div class="ps-crit-card ps-crit-card--teal">
                  <div class="ps-crit-icon ps-crit-icon--teal">
                    <v-icon size="13" color="#0d9488">mdi-clock-outline</v-icon>
                  </div>
                  <div class="ps-crit-content">
                    <span v-if="ec.minimumYears" class="ps-crit-badge ps-crit-badge--teal">
                      {{ ec.minimumYears }} {{ ec.minimumYears === 1 ? "yr" : "yrs" }}
                    </span>
                    <span v-if="ec.jobTitle" class="ps-crit-name">in {{ ec.jobTitle }}</span>
                    <span v-if="!ec.minimumYears && !ec.jobTitle" class="ps-crit-empty">Any experience</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- Other requirements -->
          <div v-if="spec.otherRequirements && spec.otherRequirements.length" class="ps-pathway__group">
            <div class="ps-pathway__group-head">
              <v-icon size="14" color="#d97706">mdi-check-decagram-outline</v-icon>
              <span>Other Requirements</span>
            </div>
            <div class="ps-crit-list">
              <div v-for="(req, ri) in spec.otherRequirements" :key="'r' + ri">
                <div class="ps-crit-card ps-crit-card--amber">
                  <div class="ps-crit-icon ps-crit-icon--amber">
                    <v-icon size="13" color="#d97706">mdi-check</v-icon>
                  </div>
                  <div class="ps-crit-content">
                    <span class="ps-crit-name">{{ req }}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
const EXT_SPEC      = "http://ihris.org/fhir/StructureDefinition/position-specification";
const EXT_QUAL_CRIT = "http://ihris.org/fhir/StructureDefinition/spec-qualification-criterion";
const EXT_EXP_CRIT  = "http://ihris.org/fhir/StructureDefinition/spec-experience-criterion";
const EXT_NAME      = "http://ihris.org/fhir/StructureDefinition/ihris-basic-name";

export default {
  name: "PositionSpecification",
  props: {
    // Pass the raw FHIR Basic resource already fetched by the parent.
    // The component only does an additional fetch for qualification names.
    resource: { type: Object, required: true },
  },

  data() {
    return {
      loading: false,
      error: null,
      specifications: [],
    };
  },

  watch: {
    resource: {
      immediate: true,
      handler(r) {
        if (r) this.parse(r);
      },
    },
  },

  methods: {
    extValue(resource, url, key) {
      const ext = (resource.extension || []).find((e) => e.url === url);
      return ext ? ext[key] : null;
    },

    subExtValue(ext, url, key) {
      const sub = (ext.extension || []).find((e) => e.url === url);
      return sub ? sub[key] : null;
    },

    async parse(resource) {
      this.loading = true;
      this.error = null;
      this.specifications = [];
      try {
        // Collect all qualification name refs for batch resolution
        const qualNameRefs = new Set();
        const rawSpecs = (resource.extension || [])
          .filter((e) => e.url === EXT_SPEC)
          .map((specExt) => {
            const groupOpCoding = (specExt.extension || []).find((e) => e.url === "spec-group-operator");
            const groupOpC = groupOpCoding ? groupOpCoding.valueCoding : null;

            const qualificationCriteria = (specExt.extension || [])
              .filter((e) => e.url === EXT_QUAL_CRIT)
              .map((critExt) => {
                const opCoding = this.subExtValue(critExt, "spec-criterion-operator", "valueCoding");
                const lvCoding = this.subExtValue(critExt, "qualification-level", "valueCoding");
                const nameRef  = this.subExtValue(critExt, "qualification-name", "valueReference");
                if (nameRef && nameRef.reference) qualNameRefs.add(nameRef.reference);
                return {
                  criterionOperator: opCoding ? opCoding.display || opCoding.code : null,
                  qualificationLevel: lvCoding ? lvCoding.display || lvCoding.code : null,
                  _qualNameRef: nameRef ? nameRef.reference : null,
                  qualificationName: nameRef ? nameRef.display || null : null,
                };
              });

            const experienceCriteria = (specExt.extension || [])
              .filter((e) => e.url === EXT_EXP_CRIT)
              .map((critExt) => {
                const opCoding = this.subExtValue(critExt, "spec-criterion-operator", "valueCoding");
                return {
                  criterionOperator: opCoding ? opCoding.display || opCoding.code : null,
                  minimumYears: this.subExtValue(critExt, "minimum-years", "valuePositiveInt"),
                  jobTitle: this.subExtValue(critExt, "job-title", "valueString"),
                };
              });

            const otherRequirements = (specExt.extension || [])
              .filter((e) => e.url === "other-requirement")
              .map((e) => e.valueString)
              .filter(Boolean);

            return {
              groupOperator: groupOpC ? groupOpC.display || groupOpC.code : null,
              qualificationCriteria,
              experienceCriteria,
              otherRequirements,
            };
          });

        // Batch-fetch qualification names
        const qualNameById = {};
        if (qualNameRefs.size > 0) {
          const ids = [...qualNameRefs].map((r) => r.split("/")[1]).filter(Boolean);
          try {
            const qnRes = await fetch(`/fhir/Basic?_id=${ids.join(",")}&_count=${ids.length}`);
            if (qnRes.ok) {
              const qnBundle = await qnRes.json();
              for (const e of (qnBundle.entry || [])) {
                if (e.resource && e.resource.resourceType === "Basic") {
                  qualNameById[e.resource.id] = this.extValue(e.resource, EXT_NAME, "valueString") || null;
                }
              }
            }
          } catch (_) { /* non-critical */ }
        }

        this.specifications = rawSpecs.map((spec) => ({
          ...spec,
          qualificationCriteria: spec.qualificationCriteria.map((qc) => {
            const refId = qc._qualNameRef ? qc._qualNameRef.split("/")[1] : null;
            return {
              criterionOperator: qc.criterionOperator,
              qualificationLevel: qc.qualificationLevel,
              qualificationName: (refId && qualNameById[refId]) || qc.qualificationName || null,
            };
          }),
        }));
      } catch (err) {
        this.error = "Could not load specifications.";
      } finally {
        this.loading = false;
      }
    },
  },
};
</script>

